def factorial(n):
    # Verificar que el número sea no negativo
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")

    # Inicializar el resultado como 1 (0! = 1)
    result = 1

    # Multiplicar iterativamente desde 2 hasta n
    for i in range(2, n + 1):
        result *= i

    return result

